'use strict';
const $=s=>document.querySelector(s),fmt=(n,d=2)=>Number(n).toFixed(d),esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let config=SRS.defaults(),result=null,tab='overview',dirty=false,q=[0,-.5,.15,1.1,.1,-.4,0],showCloud=false,ikResult=null;
try{const stored=localStorage.getItem('srs-config-v1');if(stored){const saved=JSON.parse(stored);if(!localStorage.getItem('srs-custom-axes-migrated')&&saved.configuration==='SRS-7R-YZX'&&saved.jointAxes==null){const standard=JSON.stringify(saved.limits)===JSON.stringify(SRS.defaults('SRS-7R-YZX').limits);saved.configuration='SRS-7R-XYZ';if(standard)saved.limits=SRS.defaults('SRS-7R-XYZ').limits;}const c={...SRS.defaults(saved.configuration),...saved};SRS.validate(c);config=c;}localStorage.setItem('srs-custom-axes-migrated','1');}catch(e){}
const names={overview:['PROJECT OVERVIEW','从设计规格，到关节需求。','以统一的 SRS 模型，串联机械臂正向设计的每一步。'],specs:['DESIGN SPECIFICATIONS','定义你的机械臂。','统一单位、坐标与参数来源，让后续计算始终基于同一个模型。'],kinematics:['KINEMATICS','每个关节，如何决定末端。','正运动学、几何雅可比与位置逆解；使用同一套局部旋转轴定义。'],workspace:['REACHABLE WORKSPACE','探索机械臂的可达边界。','固定随机种子的关节空间采样；显示法兰位置点云。'],statics:['STATIC ANALYSIS','看清静止时的关节负担。','负载与运动刚体自重共同作用，计算各关节的重力补偿力矩。'],dynamics:['DYNAMIC ANALYSIS','让设计进入运动。','刚体拉格朗日逆动力学，计算示例运动周期内的力矩需求。'],sizing:['JOINT MODULE REQUIREMENTS','把运动需求，转成规格。','按关节输出电机、减速器与制动保持需求，作为后续供应商匹配的输入。'],skills:['MODULAR DESIGN PIPELINE','每项能力，一个 Skill。','共用确定性计算内核与版本化数据契约，可单独运行，也可顺序编排。'],notes:['MODEL & EVIDENCE','让每项结果，都能追溯。','区分已有参数与工程假设，保留计算公式、模型范围及待补齐项。']};
const stages=[['构型建模','model'],['运动学','kinematics'],['可达空间','workspace'],['静力学','statics'],['动力学','dynamics'],['模组规格','sizing']];
function variantInfo(){return SRS.configurations().find(v=>v.id===config.configuration);}
function axisLabels(){return SRS.model(config).axisLabels;}
function sideMount(){return !!config.linkVectors||config.configuration==='SRS-7R-YZX'||config.configuration==='SRS-7R-XYZ';}
const AXIS_PRESETS={'X':[1,0,0],'-X':[-1,0,0],'Y':[0,1,0],'-Y':[0,-1,0],'Z':[0,0,1],'-Z':[0,0,-1]};
function axisEditor(j,v){const label=SRS.labelAxis(v),selected=Object.prototype.hasOwnProperty.call(AXIS_PRESETS,label)?label:'custom';return `<div class="axis-editor"><select id="axisPreset${j}" data-axis-preset="${j}" aria-label="J${j+1}局部关节轴">${[...Object.keys(AXIS_PRESETS),'custom'].map(a=>`<option value="${a}" ${a===selected?'selected':''}>${a==='custom'?'自定义向量':a+' 轴'}</option>`).join('')}</select><div class="axis-components">${v.map((x,k)=>`<label>${['x','y','z'][k]}<input id="axis${j}_${k}" data-axis-component="${j},${k}" type="number" step="0.01" value="${Number(x.toFixed(6))}" aria-label="J${j+1}轴向${['x','y','z'][k]}分量"></label>`).join('')}</div></div>`;}
function note(t,cls=''){return `<div class="note ${cls}">${t}</div>`;}
function card(title,body,meta=''){return `<section class="card"><div class="card-head"><h2>${title}</h2>${meta}</div>${body}</section>`;}
function kpi(label,value,unit,small,icon=''){return `<div class="kpi"><div class="label">${label}</div><span class="icon">${icon}</span><strong>${value}</strong><span class="unit">${unit}</span><small>${small}</small></div>`;}
function list(rows){return `<dl class="data-list">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;}
function worksheet(){return config.configuration==='WORKSHEET-7R';}
let criticalJoint=null;
let skillData=null, skillMessage='尚未运行静力学 Skill', skillBusy=false, skillInput='', skillInputSignature=null, skillRunSignature=null;
const skillKey=()=>JSON.stringify(config);
function invalidateSkill(){skillData=null;criticalJoint=null;skillRunSignature=null;skillMessage='参数发生变化，请重新准备对应模型的 Skill 输入并计算';}
function skillCurrent(){return !!skillData&&!dirty&&skillRunSignature===skillKey();}
function staticsView(){
 const ok=skillCurrent(),rows=ok?skillData.view.joints:[];
 const controls=`<div class="card-body"><p>静力学结果只能由 <b>arm-statics-parametric</b> 独立 Skill 返回。该输入必须包含完整轴向、长度、质量、质心、限位、姿态或搜索配置；<b>仅当输入几何、关节轴和限位与当前三维模型一致，姿态预览才有物理意义。</b> 本页不从简化概念参数推测真实质心。</p><div class="actions-row"><button id="loadWorksheet" class="button">载入选型表 3.612kg 示例</button><button id="pickSkillFile" class="button">上传 JSON / JSONC</button><input id="skillFile" type="file" accept=".json,.jsonc" hidden><button class="button primary" id="runSkill" ${skillBusy?'disabled':''}>${skillBusy?'正在运行…':'运行静力学 Skill'}</button></div><textarea id="skillSource" spellcheck="false" style="box-sizing:border-box;width:100%;min-height:150px;margin-top:14px;font:12px/1.5 monospace" placeholder="在此粘贴 Skill JSON / JSONC 输入（必须与当前三维模型一致）">${esc(skillInput)}</textarea><p id="skillState" role="status">${esc(skillMessage)}</p></div>`;
 let html=card('独立静力学校核 Skill · V10',controls,'<span class="chip accent">唯一静力学结果来源：Skill CLI</span>');
 if(ok){const v=skillData.view,e=skillData.payload.execution;
   html+=`<div class="kpis">${kpi('已校核关节数',v.joints.length,'','来自 Skill 的 summary')}${kpi('最大已检查重力矩',fmt(Math.max(...v.joints.map(j=>j.maxTorqueNm??0)),3),'N·m','已检查工况，非全局证明')}${kpi('计算耗时',e.elapsed_ms,'ms','外部 Skill 进程')}${kpi('计算版本',esc(v.engineVersion),'','输入哈希可追溯')}</div>`;
   html+=card('关节静力学结果',table(['关节','最大 |τ| / N·m','设计输出端 / N·m','连续能力 / N·m','裕量','临界姿态'],v.joints.map(j=>[esc(j.name),j.maxTorqueNm==null?'—':fmt(j.maxTorqueNm,4),j.requiredNm==null?'—':fmt(j.requiredNm,4),j.capacityNm==null?'未提供':fmt(j.capacityNm,4),j.margin==null?'待选型':fmt(j.margin*100,1)+'%',`<button class="button" data-skill-pose="${esc(j.name)}" ${j.criticalPose?'':'disabled'}>显示姿态</button>`])));
   html+=card('执行依据',`<div class="card-body">${list([['运行 ID',esc(v.runId)],['版本',esc(v.engineVersion)],['输入哈希',esc(v.inputSha256||'未返回')],['执行时间',esc(v.executedAt)],['执行类型',esc(e.execution_mode)]])}<p>${v.warnings.map(w=>esc(typeof w==='string'?w:JSON.stringify(w))).join('<br>')||'搜索不能证明全局最大，未做结构、碰撞与热保持校核。'}</p><div class="actions-row"><button class="button" id="skillExportJson">下载 Skill JSON</button></div></div>`);
 }
 html+=card('三维临界姿态预览',criticalOptions()+viewport(),'<span class="meta">姿态来自本次 Skill 搜索结果；关节角以弧度传递至原 SRS 三维渲染器</span>');
 return html;
}
function criticalOptions(){
 if(!skillCurrent())return '<div class="card-body"><p class="meta">请先运行静力学 Skill；搜索得到的临界姿态将出现在此处。</p></div>';
 const joints=skillData.view.joints.filter(j=>j.criticalPose);
 if(!joints.length)return '<div class="card-body"><p>Skill 未返回任何临界姿态，请检查是否启用搜索或提供典型姿态。</p></div>';
 const selected=joints.find(j=>j.name===criticalJoint);
 const options=joints.map(j=>`<option value="${esc(j.name)}" ${j.name===criticalJoint?'selected':''}>${esc(j.name)} · 最大 |τ| ${j.maxTorqueNm==null?'—':fmt(j.maxTorqueNm,3)} N·m</option>`).join('');
 const source=selected?.criticalPose?.source||'未提供';
 let detail='选择上方姿态后，将完整 J1–J7 角度（弧度）应用到三维机械臂。';
 if(selected){
   try{const angles=window.SkillClient.poseToJointAngles(selected.criticalPose,skillData.payload.result.joint_names);
     detail=`<strong>${esc(selected.name)}</strong> · 搜索来源：${esc(source)} · 已检查最大扭矩 ${selected.maxTorqueNm==null?'—':fmt(selected.maxTorqueNm,4)} N·m<br>七轴角度（°）：${angles.map((v,i)=>`${esc(skillData.payload.result.joint_names[i])}=${fmt(v*180/Math.PI,2)}`).join('　')}<br><small>临界姿态是已检查搜索范围内的最大值，不代表数学上已证明的全局最大值。</small>`;
   }catch(e){detail=esc(e.message);}
 }
 return `<div class="card-body"><div class="actions-row"><label for="criticalPosePick">最大扭矩姿态</label><select id="criticalPosePick" aria-label="选择 Skill 搜索得到的最大扭矩姿态"><option value="">请选择关节临界姿态</option>${options}</select><button class="button" id="criticalApply" ${selected?'':'disabled'}>应用所选姿态</button></div><p id="criticalPoseDetails" aria-live="polite">${detail}</p></div>`;
}
function criticalControls(){return ''; }
function activeCritical(){if(!skillCurrent()||!criticalJoint)return null;return skillData.view.joints.find(j=>j.name===criticalJoint)||null;}
function refreshCritical(){}
function criticalCompatible(){return skillCurrent();}
function selectCriticalPose(joint){
 if(!skillCurrent())return message('请先运行当前模型对应的 Skill');
 const j=skillData.view.joints.find(item=>item.name===joint);if(!j)return;
 let angles;
 try {angles=window.SkillClient.poseToJointAngles(j.criticalPose,skillData.payload.result.joint_names);}catch(e){return message(e.message);}
 if(angles.length!==7||angles.some((v,i)=>v<SRS.rad(config.limits[i][0])-1e-8||v>SRS.rad(config.limits[i][1])+1e-8))return message('姿态不符合当前三维模型的关节限位，已拒绝应用。');
 q=angles.slice();criticalJoint=joint;selectedJoint=skillData.payload.result.joint_names.indexOf(joint);render();
}
async function runSkill(){
 const raw=$('#skillSource')?.value??skillInput;skillInput=raw;
 if(!raw.trim())return message('请先提供完整的 Skill JSON / JSONC 输入');
 skillBusy=true;skillMessage='Skill 正在计算…';render();
 const signature=skillKey();
 try{
   const payload=await window.SkillClient.runStaticsSkill(raw);
   const view=window.SkillClient.makeStaticsViewModel(payload);
   if(signature!==skillKey()||dirty){invalidateSkill();skillMessage='模型已改变，丢弃过期结果';}
   else if(payload.result.joint_names.length!==7||view.joints.length!==7)throw Error('结果不是 7R 模型，拒绝加载');
   else{skillData={payload,view};skillRunSignature=signature;skillMessage='Skill 执行成功；请确认 Skill 输入模型与当前网页三维模型一致';}
 }catch(e){invalidateSkill();skillMessage='Skill 执行失败：'+e.message;}finally{skillBusy=false;render();}
}
function bindSkillPage(){
 if($('#skillSource'))$('#skillSource').oninput=e=>{skillInput=e.target.value;invalidateSkill();const state=$('#skillState');if(state)state.textContent='输入已修改，请重新运行';};
 if($('#loadWorksheet'))$('#loadWorksheet').onclick=async()=>{if(!worksheet())return message('请先在规格页选择“选型表单臂”构型，防止 Skill 输入与三维模型不一致');try{const res=await fetch('worksheet-minimal.jsonc');if(!res.ok)throw Error('示例文件不可用');skillInput=await res.text();invalidateSkill();render();}catch(e){message(e.message);}};
 if($('#pickSkillFile'))$('#pickSkillFile').onclick=()=>$('#skillFile').click();
 if($('#skillFile'))$('#skillFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024)return message('Skill 请求不可超过2MB');skillInput=await file.text();invalidateSkill();render();};
 if($('#runSkill'))$('#runSkill').onclick=runSkill;
 if($('#skillExportJson'))$('#skillExportJson').onclick=()=>download('statics_result.json',JSON.stringify(skillData.payload.result,null,2));
 document.querySelectorAll('[data-skill-pose]').forEach(b=>b.onclick=()=>selectCriticalPose(b.dataset.skillPose));
 if($('#criticalApply'))$('#criticalApply').onclick=()=>{const pick=$('#criticalPosePick');if(pick?.value)selectCriticalPose(pick.value);};
}
function poseButtons(){return worksheet()?`<div class="actions-row worksheet-poses"><button class="button" data-pose="natural">屈肘预览</button><button class="button" data-pose="zero">零位下垂</button><button class="button" data-pose="forward">前平举</button><button class="button" data-pose="side">侧平举</button><a class="inline-link" href="worksheet-minimal.jsonc" download>下载原始参数 JSONC ↓</a></div>`:'';}
function viewport(cloud=false){return `<div class="viewport"><canvas id="scene" tabindex="0" aria-label="三维机械臂：拖动空白旋转视角；拖动关节或旋转圆环调整关节角度；滚轮缩放；方向键微调"></canvas><span class="view-label">SRS / J1 ${axisLabels()[0]} / 3D</span><div class="view-toolbar"><button id="homeView" title="恢复三维视角">⌂</button><button id="cloudView" title="显示或隐藏位置点云">◎</button></div><div class="scene-controls"><label for="jointPick">操作关节</label><select id="jointPick" aria-label="选择操作关节">${Array.from({length:7},(_,j)=>`<option value="${j}">J${j+1} · ${axisLabels()[j]} 轴</option>`).join('')}</select><output id="sceneAngle">0.0°</output><span>拖关节 / 圆环旋转 · 拖空白转视角 · 滚轮缩放</span></div><span class="view-legend">${sideMount()?'Y–Z 平面侧装底座':'X–Y 平面水平底座'} · ${worksheet()?'实际七段轴心间距 · 模组外形仅为示意':'三维间距展开示意，计算模型几何不变。'}</span></div>${poseButtons()}${criticalControls()}`;}
function bars(a,b,height=160){let mx=Math.max(...a,...b,.1);return `<div class="bar-chart" style="height:${height}px">${a.map((v,i)=>`<div class="bar-column"><b>${fmt(Math.max(v,b[i]),1)}</b><div class="bars"><div class="bar gray" style="height:${Math.max(1,v/mx*100)}%" title="J${i+1} 重力峰值 ${fmt(v)} Nm"></div><div class="bar" style="height:${Math.max(1,b[i]/mx*100)}%" title="J${i+1} 动态峰值 ${fmt(b[i])} Nm"></div></div><small>J${i+1}</small></div>`).join('')}</div>`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function field(key,label,unit,help='',factor=1,step='any'){return `<div class="field"><label for="f-${key}">${label}</label><div class="input-wrap"><input id="f-${key}" data-key="${key}" data-factor="${factor}" type="number" step="${step}" value="${Number((config[key]*factor).toFixed(factor===1000?3:8))}"><span>${unit}</span></div><small class="${help.includes('假设')?'assumption':''}">${help}</small></div>`;}
function render(){const n=names[tab];$('#eyebrow').textContent=n[0];$('#heading').textContent=n[1];$('#subtitle').textContent=n[2];$('#projectLabel').textContent=config.name;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let html='';const r=result;
if(tab==='overview'){
html=`<div class="actions-row"><label for="overviewConfiguration">机械臂构型 </label><select id="overviewConfiguration">${SRS.configurations().map(v=>`<option value="${v.id}" ${config.configuration===v.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div>${worksheet()?note('选型表单臂：J1–J7轴向 −Y / X / −Z / −Y / −Z / Y / X；J1到末端635 mm，J2到末端600 mm；自重3.612 kg，负载3 kg。模块尺寸为示意，轴心间距使用输入实际值。','neutral'):''}<div class="kpis">${kpi('肩到法兰臂展',fmt(config.reach*1000,0),'mm','前期概念参数 · 可编辑','↔')}${kpi('末端附加负载',fmt(config.payload,1),'kg','点质量 · 工具质量另计','↧')}${kpi('运动部分自重',fmt(config.selfMass,worksheet()?3:1),'kg',worksheet()?'选型表质量 · 中点/轴心质心近似':'工程假设 · 不含固定底座','◇')}${kpi('驱动关节',7,'DOF','3 肩 + 1 肘 + 3 腕','⌁')}</div><div class="grid-main"><div>${card('SRS 构型预览',viewport()+`<div class="visual-footer"><span><i class="legend-dot"></i>独立关节与连接臂杆</span><span><i class="legend-dot cloud"></i>可达位置点云</span><span>右手坐标系 / Z 向上</span></div>`,`<span class="chip accent">${esc(SRS.model(config).label)}</span>`)}${card('关节力矩需求',bars(r.statics.peak,r.dynamics.peak),`<span class="meta">灰：旧内核静态估算（非 Skill 校核）　酒红：动力学轨迹峰值 / N·m</span>`)}</div><div>${card('当前设计规格',`<div class="card-body">${list([['上臂 / S → E',fmt(config.upper*1000,0)+' mm'],['前臂 / E → W',fmt(config.fore*1000,0)+' mm'],['腕 → 法兰',fmt(config.tool*1000,0)+' mm'],['关节速度上限',fmt(config.speed,0)+' °/s'],['关节加速度上限',fmt(config.accel,0)+' °/s²'],['统一减速比',fmt(config.ratio,0)+' : 1'],['安全系数',fmt(config.safety,1)]])}<div class="actions-row"><button class="inline-link" data-go="specs">编辑规格参数 →</button></div></div>`)}${card('计算摘要',`<div class="card-body">${list([['位置采样',config.samples.toLocaleString()+' 点'],['采样最大肩距',fmt(r.workspace.maxShoulderRadius*1000,0)+' mm'],['旧概念重力估算',fmt(Math.max(...r.statics.peak),1)+' N·m'],['动力学周期',fmt(r.dynamics.period,2)+' s']])}${note('当前结果为<b>概念设计需求</b>。质量、惯量及示例工况均可替换；尚未进行热与寿命校核。')}</div>`)}</div></div>${card('正向设计流程',`<div class="process">${stages.map(([a,b],i)=>`<div class="process-item"><div class="number">${String(i+1).padStart(2,'0')}</div>${a}<small>${i===0?'指定 SRS 模板':'计算已完成'}</small></div>`).join('')}</div>`,`<button class="inline-link" data-go="skills">查看 Skill 数据契约 →</button>`)}`;
}
if(tab==='specs'){
html=card('01 / 整机与几何规格',`<div class="card-body"><div class="form-grid"><div class="field"><label>项目名称</label><div class="input-wrap"><input type="text" id="projectName" maxlength="80" value="${esc(config.name)}"></div></div><div class="field"><label>机械臂构型</label><div class="input-wrap"><select id="configurationPick" aria-label="机械臂构型">${SRS.configurations().map(v=>`<option value="${v.id}" ${config.configuration===v.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></div><small>${esc(variantInfo().description)} 切换会载入模板轴向并自动重算；也可在下表逐关节覆盖。</small></div>${worksheet()?note('本构型通过下方七段向量编辑几何；三段汇总尺寸为只读，J2至J4=300、J4至J6=213、J6至末端=87 mm。'):''}${field('reach','肩到法兰臂展','mm','调整时按比例缩放三段长度',1000)}${field('upper','上臂长度 S → E','mm','初始300 mm，来自前期等效尺寸',1000)}${field('fore','前臂长度 E → W','mm','初始213 mm，来自前期等效尺寸',1000)}${field('tool','腕到法兰距离','mm','初始87 mm，来自前期等效尺寸',1000)}${field('baseHeight','肩中心高度','mm','假设：120 mm，仅影响全局坐标',1000)}${field('payload','法兰附加负载','kg','初始3 kg，含附加工具/物件质量')}${field('payloadOffset','负载质心沿法兰X偏置','mm','0 表示负载位于法兰中心',1000)}${field('selfMass','运动刚体总质量','kg',worksheet()?'选型表3.612 kg，模组与连杆计入各输出刚体':'假设：8 kg；按下表分配，排除固定底座')}</div></div>`);
html+=card('02 / 运动工况与传动假设',`<div class="card-body"><div class="form-grid">${field('speed','各关节速度上限','°/s','假设：60 °/s')}${field('accel','各关节加速度上限','°/s²','假设：120 °/s²')}${field('duty','周期运动占空比','0–1','余下时间按轨迹中心姿态保持')}${field('ratio','统一减速比','i','假设：80；输出需求可逐关节后续匹配')}${field('efficiency','驱动效率','0–1','假设：0.75，按驱动侧保守换算')}${field('safety','转矩裕量系数','≥ 1','假设：1.5')}${field('rotorInertia','单电机转子惯量','kg·m²','假设：0.00002；按最大加速度附加')}${field('viscous','输出侧黏性摩擦系数','N·m·s/rad','假设：0.02')}${field('friction','输出侧库仑摩擦','N·m','假设：0.03')}${field('samples','关节姿态采样数','点','100–50000；同时供工作空间与静力学使用',1,1)}${field('seed','随机种子','整数','固定种子便于复现',1,1)}</div></div>`);
html+=(worksheet()?card('七段几何 / 当前输出坐标系',table(['段 / 到下一轴心或末端','向量 X / mm','Y / mm','Z / mm'],config.linkVectors.map((v,j)=>['J'+(j+1)+(j===6?' → 末端':' → J'+(j+2)),...v.map((x,k)=>`<input class="small" type="number" data-vector="${j},${k}" value="${Number((x*1000).toFixed(3))}" aria-label="第${j+1}段${['X','Y','Z'][k]}毫米">`)]))) :'');
html+=card('03 / 关节轴、质量与限位',table(['关节 / 局部轴','局部方向（可指定）','转动后局部平移','质量占比 %','下限 °','上限 °'],SRS.model(config).axes.map((a,j)=>[`<span id="axisLabel${j}">J${j+1} / ${axisLabels()[j]}</span>`,axisEditor(j,a),fmt(SRS.model(config).lengths[j]*1000,0)+' mm',`<input class="small" type="number" data-mass="${j}" value="${fmt(config.massFractions[j]*100,1)}" aria-label="J${j+1}质量百分比">`,`<input class="small" type="number" data-limit="${j},0" value="${config.limits[j][0]}" aria-label="J${j+1}下限">`,`<input class="small" type="number" data-limit="${j},1" value="${config.limits[j][1]}" aria-label="J${j+1}上限">`]))+`<div class="card-body">${note('关节轴在上游关节变换后的局部坐标中定义；可选±X/±Y/±Z，或输入任意非零向量，计算时归一化。修改后点击“计算此方案”。'+(SRS.model(config).warnings.length?' '+esc(SRS.model(config).warnings.join(' ')):'') ,'neutral')}${worksheet()?note('本构型自重来自选型表；bodyComs采用同段模组轴心质量与连杆中点质量的加权质心。与静力学skill的重力矩等价，惯量与动态工况仍为概念估算。','neutral'):''}${note('质量占比合计须为100%。默认长连杆质心位于中点，球关节刚体质心位于轴线共点。默认惯量由半径35 mm的均匀杆/球估计。可在输入JSON中提供 <code>bodyComs[7][3]</code> 和 <code>inertias[7][3]</code> 替换；惯量为局部坐标系中的对角主惯量。','neutral')}<div class="actions-row"><button class="button primary" id="apply">计算此方案</button><button class="button" id="restoreAxes">恢复模板轴向</button><button class="button" id="saveConfig">导出输入 JSON</button><button class="button" id="importConfig">导入输入 JSON</button><input type="file" id="fileInput" accept=".json,application/json" hidden><button class="button quiet" id="reset">恢复示例参数</button></div></div>`);
}
if(tab==='kinematics'){
const f=SRS.fk(config,q),J=SRS.jacAt(f,f.p);html=`<div class="grid-main"><div>${card('关节姿态预览',viewport(),'<span class="chip">正运动学 · 即时计算</span>')}${card('关节角度控制',`<div class="card-body"><div class="sliders">${q.map((v,j)=>`<div class="slider"><label for="q${j}">J${j+1}<output id="qo${j}">${fmt(v*180/Math.PI,1)}°</output></label><input id="q${j}" type="range" data-q="${j}" min="${config.limits[j][0]}" max="${config.limits[j][1]}" step="0.1" value="${v*180/Math.PI}"></div>`).join('')}</div><div class="actions-row"><button class="button" id="zeroQ">零位伸展</button><button class="button" id="foldQ">折叠示例</button></div></div>`)}</div><div>${card('法兰位姿 / 基坐标系',`<div class="card-body" id="poseInfo">${poseInfo(f)}</div>`)}${card('位置逆运动学',`<div class="card-body"><p style="margin-top:0;margin-bottom:15px">阻尼最小二乘 · 6次初值尝试。只解位置，不约束末端姿态。</p><div class="stack">${['X','Y','Z'].map((a,i)=>`<div class="field"><label>目标 ${a} / mm</label><div class="input-wrap"><input type="number" id="ik${i}" value="${[350,150,250][i]}"><span>mm</span></div></div>`).join('')}</div><div class="actions-row"><button class="button primary" id="solveIK">求解并应用</button></div><p id="ikStatus">${ikResult?esc(ikResult):'输入目标点，计算一组限位内位置解。'}</p></div>`)}</div></div>${card('几何雅可比 J / 6 × 7',`<div class="card-body"><p>前3行为线速度映射，后3行为角速度映射；列对应J1–J7。单位 m/rad 与 rad/rad。</p><div class="matrix" id="jacobian">${jacText(f,J)}</div></div>`)}`;
}
if(tab==='workspace') html=`<div class="kpis">${kpi('关节姿态采样',config.samples.toLocaleString(),'点','均匀采样关节角，不是均匀采样空间')}${kpi('采样最大肩到法兰距离',fmt(r.workspace.maxShoulderRadius*1000,0),'mm','零位伸展点包含在采样中')}${kpi('X 向位置跨度',fmt((r.workspace.xyzMax[0]-r.workspace.xyzMin[0])*1000,0),'mm','基坐标系采样极值')}${kpi('随机种子',config.seed,'','同参数同种子可复现')}</div>${card('法兰可达位置点云',viewport(true)+`<div class="visual-footer"><span>显示 ${Math.min(r.points.length,5000)} / ${r.points.length} 个点</span><span>基坐标原点位于地面，肩高 ${fmt(config.baseHeight*1000,0)} mm</span></div>`, '<span class="chip accent">位置可达 · 未作碰撞筛选</span>')}<div class="small-grid">${card('采样空间包围盒',table(['轴','最小 / mm','最大 / mm'],['X','Y','Z'].map((a,i)=>[a,fmt(r.workspace.xyzMin[i]*1000,1),fmt(r.workspace.xyzMax[i]*1000,1)])))}${card('结果如何使用',`<div class="card-body">${note('点云表示当前关节限位下的可达位置样本。<b>包围盒内部的点不保证可达</b>，采样稀疏区不代表不可达。','neutral')}<p>指定位置可切换到运动学页面尝试逆解。姿态可达、碰撞、任务覆盖率和带载可达空间需要另行验证。</p><div class="actions-row"><button class="inline-link" data-go="kinematics">验证指定位置 →</button></div></div>`)}</div>`;
if(tab==='statics')html=staticsView();
if(tab==='dynamics') html=`<div class="kpis">${kpi('运动周期',fmt(r.dynamics.period,2),'s','各关节相差0.3 rad相位的正弦轨迹')}${kpi('运动占空比',fmt(config.duty*100,0),'%','其余时间在中心姿态保持')}${kpi('轨迹采样',64,'点/周期','每点计算完整逆动力学')}${kpi('最大轨迹力矩',fmt(Math.max(...r.dynamics.peak),2),'N·m','惯性 + 速度积 + 重力 + 摩擦')}</div>${card('关节力矩曲线 / 一个运动周期',`<div class="card-body"><canvas id="torquePlot" class="plot" aria-label="七个关节的力矩时间曲线"></canvas><p>J1–J7以不同深浅颜色显示；RMS包含非运动时段的中心姿态重力保持，不按零力矩处理。</p></div>`,'<span class="chip accent">刚体逆动力学 · 假设惯量</span>')}${card('示例工况结果',table(['关节','峰值 / N·m','整周期RMS / N·m','保持 / N·m','峰值速度 / °/s','峰值加速度 / °/s²','峰值机械功率 / W'],r.dynamics.peak.map((v,j)=>['J'+(j+1),fmt(v,3),fmt(r.dynamics.rms[j],3),fmt(r.dynamics.hold[j],3),fmt(r.dynamics.speed[j]*180/Math.PI,1),fmt(r.dynamics.accel[j]*180/Math.PI,1),fmt(r.dynamics.power[j],2)])))}<div class="formula">τ = M(q)q̈ + C(q,q̇)q̇ + G(q) + Bq̇ + τc sign(q̇)<br>M = Σ (m Jvᵀ Jv + Jωᵀ R ICOM Rᵀ Jω)</div>${note('已实现刚体惯性与科氏/离心项；质量矩阵偏导采用中心差分。默认惯量来自均匀杆/球估计，附加负载按点质量处理。示例轨迹不能覆盖实际任务全部工况，速度上限变化也可能受加速度上限约束。')}`;
if(tab==='sizing') html=`<div class="kpis">${kpi('关节规格输出',7,'组','每个关节独立计算需求包络')}${kpi('统一减速比',fmt(config.ratio,0),': 1','当前用户输入值，未进行速比寻优')}${kpi('传动效率',fmt(config.efficiency*100,0),'%','电机侧换算采用驱动效率')}${kpi('转矩安全系数',fmt(config.safety,1),'×','应用于负载转矩和转子加速')}</div>${card('旧概念选型估算（非 Skill 校核）',table(['关节','额定输出转矩 ≥ N·m','峰值输出转矩 ≥ N·m','最高输出转速 ≥ rpm','电机侧制动矩 ≥ N·m'],r.joints.map(j=>[j.joint,fmt(j.outputRated,3),fmt(j.outputPeak,3),fmt(config.speed/6,1),fmt(j.brakeHolding,3)])))}${card('电机轴端需求',table(['关节','额定转矩 ≥ N·m','峰值转矩 ≥ N·m','最高转速 ≥ rpm','保守转矩×转速包络 / W'],r.joints.map(j=>[j.joint,fmt(j.motorRated,3),fmt(j.motorPeak,3),fmt(j.motorRpm,0),fmt(j.motorPowerEnvelope,1)])))}<div class="small-grid">${card('计算关系',`<div class="card-body"><div class="formula">Tred,peak = K · max(Tg,sampled, Tdyn,peak)<br>Tred,rated = K · max(Trms, |Thold|)<br>Tmotor = Tred / (i·η) + K·Jrotor·i·αmax<br>nmotor = i · ωmax · 60 / (2π)</div><p>电机额定转矩额外叠加最大转子加速力矩，属于保守需求。功率列为峰值转矩与最高转速的乘积包络，不是额定功率或实际同时发生的功率。</p></div>`)}${card('供应商匹配前还需补齐',`<div class="card-body">${note('当前输出为<b>规格需求</b>，未接入产品目录，未宣称选定具体电机或减速器型号。')}<p>补齐实际任务轨迹、CAD质量/惯量、减速器惯量、转矩–转速曲线、热阻与温升、制动工况、轴承力/力矩、寿命与刚度。模组质量变化应回写模型并重新运行。</p><div class="actions-row"><button class="button" id="exportCsv">↓ 导出规格 CSV</button></div></div>`)}</div>`;
if(tab==='skills'){
const defs=[['构型选择与参数建模','arm-configure','规格 JSON','标准化 model.json','选择肩部轴序模板，验证臂展、限位、质量分配、坐标约定。当前仅支持指定构型，后续扩展多构型候选评分。'],['运动学计算','arm-kinematics','规格 + 关节角 / 目标点','位姿、6×7雅可比、位置IK','统一局部轴线定义，正运动学与阻尼位置逆解；不宣称已校核目标姿态。'],['可达空间计算','arm-workspace','规格 + 采样数 / 种子','点云、XYZ包围盒、采样肩距','关节空间蒙特卡洛采样，保留种子；与真实碰撞自由、带载可达空间区分。'],['静力学校核','arm-statics','规格 + 质量 / 质心','独立 Skill 的扭矩、极值与临界姿态','仅由服务端 arm-statics-parametric 计算；不复用浏览器静力学数值。'],['动力学计算','arm-dynamics','规格 + 惯量 / 速度 / 加速度','力矩时序、RMS、峰值、速度','以质量矩阵与Christoffel系数求逆动力学；当前内置正弦工况。'],['关节模组规格','arm-sizing','静力学 + 动力学输出','每关节电机/减速器需求','同输入快照检查；统一安全系数、效率、速比及转子加速项；输出产品匹配前的需求。']];
html=card('统一数据流',`<div class="card-body"><div class="process" style="padding:8px 0 20px">${stages.map(([a,b],i)=>`<div class="process-item"><div class="number">${i+1}</div>${a}<small>JSON → JSON</small></div>`).join('')}</div>${note('静力学分析页面通过服务端调用独立 Skill；其他概念设计功能保留原浏览器内核。<b>需将实际 Skill 部署至服务端</b>；Skill可在Codex中独立执行，也可由总控Skill顺序运行。','neutral')}<p>总控：<code>$arm-design-pipeline</code>。每次输出携带schema版本、完整输入快照、计算方法和假设。修改任何几何、负载或运动参数后，重新运行下游结果；禁止混用不同输入版本的静力学与动力学数据。</p></div>`);
html+=`<div class="skill-grid">${defs.map(([title,id,inp,out,desc],i)=>`<section class="skill-card"><div class="num">SKILL ${String(i+1).padStart(2,'0')} / ${id}</div><h2>${title}</h2><p>${desc}</p><div class="io"><b>INPUT</b> ${inp}<br><b>OUTPUT</b> ${out}</div><div class="actions-row"><button class="inline-link" data-go="${['specs','kinematics','workspace','statics','dynamics','sizing'][i]}">打开功能 →</button></div></section>`).join('')}</div>`;
}
if(tab==='notes')html=card('示例参数的来源与解释',`<div class="card-body">${list([['600 mm / 3 kg','前期“机械臂概念学习”示例'],['300 / 213 / 87 mm','原图为等效投影距离；本版作为理想几何假设'],[worksheet()?'3.612 kg / 3 kg / 9.8 m/s²':'8 kg / 60°/s / 120°/s²',worksheet()?'选型表单臂及本次静力学输入；速度、惯量为概念假设':'本版工程假设，尚无原始规格依据'],['肩与腕轴线','肩部'+axisLabels().slice(0,3).join('–')+'；肘Y；腕X–Y–X'],['旧版 reachability.py','保留旋转后平移方法；重新定义SRS轴线几何']])}<p>旧 example_input.json 是7段串联旋转链，长度总和760 mm，不能直接当作600 mm SRS模型。前期示意图中的DH表也未作为计算输入。当前使用明确的轴线—平移模型，${worksheet()?'本构型零位沿−Z下垂、七段轴心分离；重力9.8 m/s²':'零位沿+X伸展、基坐标Z向上'}，重力沿−Z。类人肩部模板现为J1绕X、J2绕Y、J3绕Z。可在规格表中逐关节覆盖方向；正转遵循右手定则。前伸零位下J1绕臂轴旋转，J2负角抬臂。</p></div>`)+card('计算假设与验证范围',`<div class="card-body text-body"><ul>${r.assumptions.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p>质量矩阵采用刚体动能推导，逆动力学包含惯性、速度积、重力与摩擦项。数学依据：<a href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/chapter-8-1-lagrangian-formulation-of-dynamics-part-1-of-2/" target="_blank" rel="noopener">Northwestern · Modern Robotics / Lagrangian Dynamics ↗</a>。</p><p>惯量输入限定为各连杆局部坐标中的对角主惯量。若CAD惯量含非零积惯量，需要先将模型坐标变换至主轴或扩展内核支持完整3×3张量。</p></div>`)+card('工程闭环的后续接口',`<div class="card-body text-body">${table(['阶段','需要补充','回写内容'],[['多构型寻优','候选构型、任务点、障碍与评价权重','构型、杆长、冗余利用率'],['真实任务校核','位姿轨迹、周期、停留与接触力','全工况力矩、速度、功率'],['产品与寿命匹配','厂商目录、热、轴承载荷、寿命曲线','实际模组质量、惯量与效率'],['结构与仿真验证','CAD、URDF、接触/碰撞模型','更新后的几何与动力学参数']])}<p>后续调度服务建议采用任务队列调用确定性计算脚本，Skill负责输入检查、知识检索与结果解释；网页通过任务API提交输入并查看真实执行状态。不能仅凭SKILL.md在网页中自动运行大模型。</p></div>`);
$('#content').innerHTML=html;bindPage();requestAnimationFrame(()=>{if($('#scene'))setupScene(tab==='workspace');if($('#torquePlot'))plot();});}
function poseInfo(f){return list(['X','Y','Z'].map((a,i)=>[a+' / mm',fmt(f.p[i]*1000,2)]))+`<p>旋转矩阵 R（无量纲）</p><div class="matrix">${f.R.map(r=>r.map(v=>fmt(v,4).padStart(8)).join(' ')).join('\n')}</div>`;}
function jacText(f,J){return Array.from({length:6},(_,i)=>Array.from({length:7},(_,j)=>fmt(i<3?J[j][i]:f.axes[j][i-3],4).padStart(8)).join(' ')).join('\n');}
function message(t){$('#message').textContent=t;$('#message').style.display=t?'block':'none';}
function markDirty(){invalidateSkill();dirty=true;$('#state').className='status dirty';$('#state').textContent='参数已修改 · 等待重算';$('#export').disabled=true;message('参数已修改，页面结果来自上一次计算。请运行全流程后查看或导出更新结果。');}
function syncInputs(){document.querySelectorAll('[data-key]').forEach(el=>{el.value=Number((config[el.dataset.key]*Number(el.dataset.factor)).toFixed(el.dataset.factor==='1000'?3:8));});}
async function calculate(){invalidateSkill();const b=$('#run');b.disabled=true;b.textContent='计算中…';await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));try{SRS.validate(config);if(config.jointAxes!=null)config.jointAxes=SRS.model(config).axes;result=SRS.run(structuredClone(config));q=q.map((v,j)=>Math.max(SRS.rad(config.limits[j][0]),Math.min(SRS.rad(config.limits[j][1]),v)));dirty=false;$('#state').className='status';$('#state').textContent='已计算 · 初步估算';$('#export').disabled=false;message('');try{localStorage.setItem('srs-config-v1',JSON.stringify(config));}catch(e){}render();}catch(e){message(e.message);markDirty();message(e.message);}finally{b.disabled=false;b.textContent='▶ 运行全流程';}}
async function switchConfiguration(id){criticalJoint=null;if(id==='WORKSHEET-7R'||worksheet()){config=SRS.defaults(id);q=id==='WORKSHEET-7R'?[.65,-.65,.2,1,0,0,0]:Array(7).fill(0);selectedJoint=0;markDirty();await calculate();return;}const previous=SRS.defaults(config.configuration),newDefaults=SRS.defaults(id),standardLimits=JSON.stringify(config.limits)===JSON.stringify(previous.limits);config.configuration=id;config.jointAxes=null;if(standardLimits)config.limits=newDefaults.limits;config.provenance={...config.provenance,configuration:'用户选择：'+variantInfo().label};q=Array(7).fill(0);selectedJoint=0;markDirty();await calculate();}
function setJointAxis(j,vector,skipComponent=null){const axes=config.jointAxes?config.jointAxes.map(v=>v.slice()):SRS.model(config).axes.map(v=>v.slice());axes[j]=vector.slice();config.jointAxes=axes;config.provenance={...config.provenance,jointAxes:'用户逐关节指定局部方向'};q=Array(7).fill(0);for(let k=0;k<3;k++){const el=$('#axis'+j+'_'+k);if(el&&k!==skipComponent)el.value=vector[k];}const preset=$('#axisPreset'+j),valid=vector.every(Number.isFinite)&&Math.hypot(...vector)>1e-10,label=valid?SRS.labelAxis(vector.map(x=>x/Math.hypot(...vector))):'custom';if(preset)preset.value=Object.prototype.hasOwnProperty.call(AXIS_PRESETS,label)?label:'custom';if($('#axisLabel'+j))$('#axisLabel'+j).textContent='J'+(j+1)+' / '+(valid?label:'待校验');markDirty();}
function setAxisComponent(j,k,value){const v=(config.jointAxes?config.jointAxes:SRS.model(config).axes)[j].slice();v[k]=value;setJointAxis(j,v,k);}
function bindPage(){bindSkillPage();if($('#criticalPosePick'))$('#criticalPosePick').onchange=e=>{if(e.target.value)selectCriticalPose(e.target.value);};if($('#overviewConfiguration'))$('#overviewConfiguration').onchange=e=>switchConfiguration(e.target.value);
if(worksheet())for(const k of ['reach','upper','fore','tool']){const el=$('#f-'+k);if(el){el.readOnly=true;el.title='由七段向量决定，请在七段几何表中编辑';}}
document.querySelectorAll('[data-vector]').forEach(el=>el.oninput=()=>{const [j,k]=el.dataset.vector.split(',').map(Number);config.linkVectors[j][k]=el.valueAsNumber/1000;const masses=[1.061,.575,.705,.565,.282,.212,.212],links=[.1,.09,.22,.08,.12,.05,.05];config.bodyComs[j]=config.linkVectors[j].map(v=>v*.5*links[j]/masses[j]);const L=config.linkVectors.map(v=>Math.hypot(...v));config.upper=L[1]+L[2];config.fore=L[3]+L[4];config.tool=L[5]+L[6];config.reach=config.upper+config.fore+config.tool;syncInputs();markDirty();});
document.querySelectorAll('[data-pose]').forEach(el=>el.onclick=()=>{const poses={zero:[0,0,0,0,0,0,0],forward:[Math.PI/2,0,0,0,0,0,0],side:[0,-Math.PI/2,0,0,0,0,0],natural:[.65,-.65,.2,1,0,0,0]};q=poses[el.dataset.pose].map((v,j)=>Math.max(SRS.rad(config.limits[j][0]),Math.min(SRS.rad(config.limits[j][1]),v)));render();});document.querySelectorAll('[data-axis-preset]').forEach(el=>el.onchange=()=>{if(el.value==='custom'){$('#axis'+el.dataset.axisPreset+'_0')?.focus();return;}setJointAxis(+el.dataset.axisPreset,AXIS_PRESETS[el.value]);});document.querySelectorAll('[data-axis-component]').forEach(el=>el.oninput=()=>{const [j,k]=el.dataset.axisComponent.split(',').map(Number);setAxisComponent(j,k,el.valueAsNumber);});if($('#restoreAxes'))$('#restoreAxes').onclick=()=>{config.jointAxes=null;q=Array(7).fill(0);calculate();};if($('#configurationPick'))$('#configurationPick').onchange=e=>switchConfiguration(e.target.value);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{const key=el.dataset.key,old=config[key],v=el.valueAsNumber/Number(el.dataset.factor);config[key]=v;config.provenance={...config.provenance,[key]:'用户在网页中编辑'};if(key==='reach'&&v>0&&old>0){['upper','fore','tool'].forEach(k=>config[k]*=v/old);syncInputs();}else if(['upper','fore','tool'].includes(key)){config.reach=config.upper+config.fore+config.tool;const reach=$('#f-reach');if(reach)reach.value=fmt(config.reach*1000,1);}markDirty();});if($('#projectName'))$('#projectName').oninput=e=>{config.name=e.target.value;markDirty();};document.querySelectorAll('[data-mass]').forEach(el=>el.oninput=()=>{config.massFractions[+el.dataset.mass]=el.valueAsNumber/100;markDirty();});document.querySelectorAll('[data-limit]').forEach(el=>el.oninput=()=>{const [j,k]=el.dataset.limit.split(',').map(Number);config.limits[j][k]=el.valueAsNumber;markDirty();});
if($('#apply'))$('#apply').onclick=calculate;if($('#saveConfig'))$('#saveConfig').onclick=()=>downloadConfig();if($('#reset'))$('#reset').onclick=()=>{config=SRS.defaults();q=[0,-.5,.15,1.1,.1,-.4,0];calculate();};if($('#importConfig')){$('#importConfig').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('输入JSON文件须小于1 MB');const raw=JSON.parse(await file.text()),next={...SRS.defaults(raw.configuration),...raw};SRS.validate(next);config=next;await calculate();}catch(e){message('导入失败：'+e.message);}};}
document.querySelectorAll('[data-q]').forEach(el=>el.oninput=()=>updateJoint(+el.dataset.q,SRS.rad(el.valueAsNumber)));if($('#zeroQ'))$('#zeroQ').onclick=()=>{q=Array(7).fill(0).map((v,j)=>Math.max(SRS.rad(config.limits[j][0]),Math.min(SRS.rad(config.limits[j][1]),0)));render();};if($('#foldQ'))$('#foldQ').onclick=()=>{q=(config.configuration==='SRS-7R-YZX'?[-.5,0,.15,1.1,.1,-.4,0]:[0,-.5,.15,1.1,.1,-.4,0]).map((v,j)=>Math.max(SRS.rad(config.limits[j][0]),Math.min(SRS.rad(config.limits[j][1]),v)));render();};if($('#solveIK'))$('#solveIK').onclick=()=>{try{const target=[0,1,2].map(i=>$('#ik'+i).valueAsNumber/1000),ik=SRS.ik(config,target,q);if(ik.converged)q=ik.q;ikResult=(ik.converged?'位置逆解收敛':'未收敛，保留原姿态')+'；位置残差 '+fmt(ik.error*1000,3)+' mm。姿态未约束。';render();}catch(e){message(e.message);}};if($('#exportCsv'))$('#exportCsv').onclick=()=>{if(dirty)return message('请先重算更新结果。');exportData('csv');};}
function go(t){if(dirty&&t!=='specs'){message('请先在“规格与模型”修正参数并运行全流程，再查看更新结果。');return;}tab=t;history.replaceState(null,'','#'+t);render();window.scrollTo({top:0});}
let sceneState=null,selectedJoint=1;
function updateJoint(j,value){q[j]=Math.max(SRS.rad(config.limits[j][0]),Math.min(SRS.rad(config.limits[j][1]),value));const slider=$('#q'+j),out=$('#qo'+j);if(slider)slider.value=q[j]*180/Math.PI;if(out)out.textContent=fmt(q[j]*180/Math.PI,1)+'°';const f=SRS.fk(config,q);if($('#poseInfo'))$('#poseInfo').innerHTML=poseInfo(f);if($('#jacobian'))$('#jacobian').textContent=jacText(f,SRS.jacAt(f,f.p));refreshCritical();drawScene();}
function setupScene(cloud){const cv=$('#scene');sceneState=new Arm3D(cv,{cloud:cloud||showCloud,state:()=>({c:config,q,points:result?.points||[]}),change:updateJoint,select:j=>{selectedJoint=j;},drawn:(j,value)=>{const pick=$('#jointPick'),angle=$('#sceneAngle');if(pick)pick.value=String(j);if(angle)angle.textContent=fmt(value*180/Math.PI,1)+'°';}});sceneState.selected=selectedJoint;$('#jointPick').onchange=e=>{selectedJoint=+e.target.value;sceneState.choose(selectedJoint);};$('#homeView').onclick=()=>sceneState.reset();$('#cloudView').onclick=()=>{sceneState.cloud=!sceneState.cloud;showCloud=sceneState.cloud;drawScene();};drawScene();}
function drawScene(){if(sceneState&&document.body.contains(sceneState.cv))sceneState.render();}
function plot(){const cv=$('#torquePlot'),W=cv.clientWidth,H=260,dpr=devicePixelRatio||1;cv.width=W*dpr;cv.height=H*dpr;const ctx=cv.getContext('2d');ctx.scale(dpr,dpr);const series=result.dynamics.series,min=Math.min(0,...series.flatMap(s=>s.tau)),max=Math.max(...series.flatMap(s=>s.tau)),range=Math.max(1,max-min),left=43,right=W-16,top=22,bottom=217;function y(v){return bottom-(v-min)/range*(bottom-top);}ctx.font='9px monospace';for(let i=0;i<=4;i++){let v=min+range*i/4;ctx.strokeStyle='#eceeea';ctx.beginPath();ctx.moveTo(left,y(v));ctx.lineTo(right,y(v));ctx.stroke();ctx.fillStyle='#92999d';ctx.fillText(fmt(v,1),3,y(v)+3);}const colors=['#758d96','#84384c','#c99aa9','#4d7a6f','#9aaa8c','#a77d62','#92949c'];for(let j=0;j<7;j++){ctx.strokeStyle=colors[j];ctx.lineWidth=1.7;ctx.beginPath();series.forEach((v,i)=>{const x=left+i/(series.length-1)*(right-left);if(!i)ctx.moveTo(x,y(v.tau[j]));else ctx.lineTo(x,y(v.tau[j]));});ctx.stroke();ctx.fillStyle=colors[j];ctx.fillText('J'+(j+1),left+j*43,248);}ctx.fillStyle='#92999d';ctx.fillText('0 s',left,232);ctx.fillText(fmt(result.dynamics.period,2)+' s',right-40,232);ctx.fillText('N·m',4,10);}
function download(name,data,type='application/json'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function downloadConfig(){try{SRS.validate(config);download('srs-input.json',JSON.stringify(config,null,2));}catch(e){message(e.message);}}
function exportData(kind){if(kind==='config')return downloadConfig();if(dirty)return message('请先运行全流程更新计算结果。');if(kind==='json')download('srs-design-results.json',JSON.stringify(result,null,2));if(kind==='csv'){const keys=Object.keys(result.joints[0]),rows=[keys.join(','),...result.joints.map(j=>keys.map(k=>'"'+String(j[k]).replace(/"/g,'""')+'"').join(','))];rows.push('');rows.push('"NOTE","SI units: torque Nm, speed rpm; preliminary requirements. See full JSON for assumptions."');download('srs-joint-requirements.csv','\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8');}if(kind==='report'){const report=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>SRS设计分析报告</title><style>body{font:14px/1.8 sans-serif;max-width:1000px;margin:45px auto;color:#303840}h1{color:#84384c}table{border-collapse:collapse;width:100%;font-size:12px}td,th{border:1px solid #ddd;padding:10px}th{background:#f5f1f2}code{background:#f5f5f3}pre{white-space:pre-wrap;font-size:11px}@media print{body{margin:10mm}h2{break-after:avoid}tr{break-inside:avoid}}</style><h1>${esc(config.name)} · 机械臂概念设计报告</h1><p>生成时间：${esc(result.generated_at)}　内核：${result.engine_version}</p><h2>规格与模型</h2><p>${esc(variantInfo().label)}；肩部轴序 ${axisLabels().slice(0,3).join('–')}；肩到法兰臂展 ${fmt(config.reach*1000,0)} mm；负载 ${config.payload} kg；运动部分自重 ${config.selfMass} kg。默认质量与惯量为工程估计。</p><h2>关节需求</h2>${table(['关节','减速器额定 Nm','减速器峰值 Nm','电机额定 Nm','电机峰值 Nm','电机最高 rpm'],result.joints.map(j=>[j.joint,fmt(j.outputRated,3),fmt(j.outputPeak,3),fmt(j.motorRated,3),fmt(j.motorPeak,3),fmt(j.motorRpm,0)]))}<h2>结果解释</h2><p>工作空间 ${config.samples} 个关节姿态样本；位置可达性未检查碰撞或姿态。静态峰值为采样估计。动力学采用 ${fmt(result.dynamics.period)} s正弦运动周期、64点采样，运动占空比 ${config.duty}。</p><h2>方法</h2><p>τ=Mq̈+Cq̇+G+Bq̇+τc sign(q̇)。电机转矩按速比与效率换算，额外叠加最大转子加速力矩。功率包络不等于额定功率。<a href="${result.sources[0]}">Modern Robotics数学依据</a></p><h2>假设和未校核项</h2><ul>${result.assumptions.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h2>完整输入快照（SI单位）</h2><pre>${esc(JSON.stringify(config,null,2))}</pre></html>`;download('srs-design-report.html',report,'text/html;charset=utf-8');}$('#exports').close();}
$('#nav').onclick=e=>{const b=e.target.closest('[data-tab]');if(b)go(b.dataset.tab);};$('#run').onclick=calculate;$('#export').onclick=()=>$('#exports').showModal();$('#closeExport').onclick=()=>$('#exports').close();document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportData(b.dataset.export));window.addEventListener('resize',()=>{drawScene();if($('#torquePlot'))plot();});
if(new URLSearchParams(location.search).get('model')==='worksheet'){config=SRS.defaults('WORKSHEET-7R');q=[.65,-.65,.2,1,0,0,0];}
const hash=location.hash.slice(1);if(names[hash])tab=hash;calculate();
